#!/usr/bin/env python3
# luxarch:fleet-start-after-compact hook v4 - DO NOT edit this file - it is emitted by `luxarch --emit hooks`; re-emit to update.
"""After any compaction, tell the agent to run `/fleet-start`; when it runs, tell the agent who it
is, where its owner order is, and the owner's notes of this session.

Claude Code compacts on its own (when the context fills, and while a session sits idle), so "the
owner runs /compact, then /fleet-start" does not describe every compact. The CLAUDE.md line asking
for `/fleet-start` after a compact only works if someone remembers it; this hook fires on the event.

The owner names each session for its job, `[<repo> <role>]` (`[shop mypy]`), and Claude Code
records that name in the session's transcript. An owner order is one of two things, both the
owner's own: a LuxPM issue the OWNER labelled `owner-order` (and `agent:<role>` for one role), or
the note of a `/fleet-start <note>` the owner typed. No agent adds the label; work a note names
that no open issue covers, the agent files itself, `in_progress`. So the context
this hook adds names the agent, its role, the exact LuxPM query for its labelled owner orders, its
queue, and every `/fleet-start` note of this session verbatim (`fleet-start-gate` records them),
so a compact loses none of them.

The queue follows FLEET-AGENT-CONDUCT-STANDARD, "Every open issue is routed". For a role the
committed `.luxarch.toml` declares (`[agents] roles`), it is the issues labelled with the role's
one spelling (`_handoffs.role_label`, which `no-self-park` checks every sent label against), any
open state, every page (the ones whose `waiting_on` names its role, a request or a reply it owes,
first). Its owner orders are the ones labelled for its role and the ones labelled for no role;
one labelled for another role is that agent's. Once the owner has said go, it also claims an
open issue with no `agent:` label, in any layout, only by reading that issue and judging its work
to be its role's, one issue per update; a nested app tree (`apps/ios/` with its own CLAUDE.md) is
only a hint for that judgement, and an issue that names no role's work goes to the first declared
role, which any agent may route it to. An issue whose label reads as a route but is not exactly
a declared role's (`agent:iOS`, `agent-ios`, a lookalike letter) is listed as "respell to
`agent:<role>`": its own role's agent respells it; one naming no declared role is unrouted. A
role over `_handoffs.ROLE_MAX` characters is refused (LuxPM cuts a label at 50), and said so. In a
repo that declares no roles, the queue is every open
issue by state: `in_progress`, `todo`, `backlog`, every page. A session whose role is not
declared, in a repo that declares roles, is routed nothing and adds no `agent:` label. `on_hold`
issues wait on the owner: they are listed by their own query, named on one line and not counted
as work.

SessionStart(compact): its stdout lands in the post-compaction context. UserPromptSubmit: when the
whole prompt is `/fleet-start` (plain or as Claude Code's tags), its stdout lands beside the skill;
a note after the command is the owner's instruction and go-ahead. Any other prompt adds nothing. A
hook cannot invoke a skill, so this is text the agent reads, not a call. Never blocks, never errors
out.
"""

from __future__ import annotations

import contextlib
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).parent))
from _handoffs import (  # sibling helper, loaded by path
    ROLE_MAX,
    agent_role,
    declared_roles,
    refused_roles,
    role_label,
    role_name,
)
from _ledger import (
    OWNER_ORDER_LABEL,
    agent_name,
    event_cwd,
    owner_notes,
    read_event,
    repo_project,
    start_note,
    tree_dir,
)

_COMPACTED = (
    "This session was just compacted. Before anything else, run `/fleet-start`: re-read this "
    "repo's CLAUDE.md and the conduct standard's sections it names, and rehydrate from LuxPM. "
    "The summary above is not the state; LuxPM and the repo are. A compact is not a new start: "
    "the go-ahead this session already had stands, so after rehydrating carry on with your owner "
    "order without waiting. Only a `/fleet-start` the owner types with no note makes you wait "
    "for the owner's next message."
)
_UNREADABLE = (OSError, ValueError)
_PAGES = "every page (`offset` until the output names no next one)"


def _on_hold(where: str) -> str:
    return (
        f' The on_hold ones, luxpm_list_issues({where}state="on_hold"), {_PAGES}, wait on the '
        "owner: name them on one line, waiting on the owner, and do not count them as work."
    )


def _refused(refused: list[str]) -> str:
    """The roles `[agents] roles` names that LuxPM could not store a label for."""
    if not refused:
        return ""
    return (
        f" [agents] roles also names {', '.join(f'`{r}`' for r in refused)}, over {ROLE_MAX} "
        "characters: LuxPM cuts a label at 50, so it routes nothing until the owner renames it."
    )


def _queue(where: str, role: str, roles: list[str]) -> str:
    """The agent's queue, as FLEET-AGENT-CONDUCT-STANDARD, "Every open issue is routed" says."""
    if not roles:
        return (
            f" Then your queue, every open issue here: luxpm_list_issues({where}state="
            '"in_progress"), then state="todo", then state="backlog", '
            f"{_PAGES}. Verify a backlog one before you work it.{_on_hold(where)}"
        )
    declared = ", ".join(roles)
    role = role_name(role)
    refused = refused_roles()
    if role not in roles:
        who = f"`{role}` is not a role" if role else "Your name carries no role"
        why = (
            f" `{role}` is over {ROLE_MAX} characters, and LuxPM cuts a label at 50, so it "
            "can have no `agent:` label: the owner renames it in .luxarch.toml."
            if role in refused
            else ""
        )
        return (
            f" {who} this repo declares ([agents] roles: {declared}), so no issue is routed to "
            f"you and you add no `agent:` label: ask the owner which declared role you are."
            f"{why}{_on_hold(where)}"
        )
    mine, first = role_label(role), role_label(roles[0])
    routes = ", ".join(f"`{role_label(r)}`" for r in roles)
    return (
        f' Then your queue: luxpm_list_issues({where}labels=["{mine}"]), every open one, '
        f"backlog included, {_PAGES}, skipping an owner order (it also carries `owner-order`; "
        f"its labels are the owner's). Those whose waiting_on names your role (\"{role} agent: "
        '…") are a request, or a reply you owe. Answer each before the rest of your queue: do '
        "the step, then hand it back (the asker's `agent:` label in place of "
        f"`{mine}`, waiting_on naming the asker, in one update) or close it with waiting_on "
        f"cleared and `{mine}` dropped. Then the open issues routed to no declared role: "
        f'luxpm_list_issues({where}state="in_progress"), then state="todo", then '
        f'state="backlog", {_PAGES}, skipping each that carries one of this repo\'s routes '
        f"({routes}). Of the rest, one with a label that reads as a route and is none of them "
        "(`agent:iOS`, `agent:ios_app`, `agent-ios`, a fullwidth colon or a lookalike letter) "
        'you list as "respell to `agent:<role>`": one that names your role you respell to '
        f"`{mine}` in its own update; one that names another declared role is that agent's to "
        "respell; one that names no declared role is unrouted, like those with no label. Once "
        "the owner has said go, claim one only by reading it and judging its work to be your "
        f"role's, then adding `{mine}` (spelled exactly so) in that issue's own update, one "
        "issue per update. A nested app tree (a directory with its own CLAUDE.md, such as "
        "apps/ios/) is only a hint for that judgement. One that names no role's work goes to "
        f"`{first}`, the first role declared: any agent may route it there. An issue labelled "
        "for another role is that agent's: ask it with a comment, never relabel it. Name how "
        f"many are left unlabelled.{_refused(refused)}{_on_hold(where)}"
    )


def _identity(ev: dict[str, object]) -> str:
    name = agent_name(str(ev.get("transcript_path") or ""))
    role = agent_role(name)
    try:
        project = repo_project(tree_dir()) or repo_project(event_cwd())
    except OSError:
        project = ""
    where = f'project="{project}", ' if project else ""
    if not name:
        who = (
            "This session has no name. The owner names each agent for its job, "
            "`[<repo> <role>]`; until it has one, your owner orders are the ones for every agent "
            "here."
        )
    elif not role:
        who = (
            f"You are `{name}`, with no role in the name: your owner orders are the ones for "
            "every agent here."
        )
    else:
        who = f"You are `{name}`, role `{role}`."
    roles = declared_roles()
    queries = (
        f'luxpm_list_issues({where}labels=["{OWNER_ORDER_LABEL}", "{role_label(role)}"])'
        f' and luxpm_list_issues({where}labels=["{OWNER_ORDER_LABEL}"])'
        if role
        else f'luxpm_list_issues({where}labels=["{OWNER_ORDER_LABEL}"])'
    )
    ours = (
        " Of the second list, yours are the orders with no `agent:` label (for every agent "
        "here); one labelled for another role is that agent's: skip it."
        if role and roles
        else ""
    )
    return (
        f"{who} Your first LuxPM call is {queries}: an open owner order is your work, ahead of "
        f"the open issues, the guard reds and every queue.{ours} Only work that blocks other "
        "agents now interrupts it, and you say so when it does. Only the owner labels, parks or "
        f"cancels an owner order.{_queue(where, role, roles)}"
    )


def _notes(current: str = "") -> str:
    """Every `/fleet-start` note of this session, verbatim, with the one being typed now."""
    notes = [n["note"] for n in owner_notes()]
    if current and (not notes or notes[-1] != current):
        notes.append(current)
    if not notes:
        return ""
    listed = "".join(f"\n  {i}. {n}" for i, n in enumerate(notes, 1))
    return (
        "\nThe owner's orders this session, verbatim (each a `/fleet-start <note>` the owner "
        f"typed):{listed}\nRecord each one verbatim as an activity on the issue you work it in "
        "(luxpm_log_activity). Work a note names that no open issue covers, you file yourself "
        "(luxpm_create_issue in this repo's project, with a title, state in_progress, "
        "the note quoted, and in a repo with [agents] roles your own `agent:<role>`), then "
        "start in its worktree; never ask the owner to file it."
    )


def _text(ev: dict[str, object]) -> str:
    if ev.get("hook_event_name") == "UserPromptSubmit":
        note = start_note(str(ev.get("prompt") or ""))
        if note is None:
            return ""
        then = (
            "The owner left a note with /fleet-start: it is your instruction and your go-ahead."
            if note
            else "No note came with /fleet-start: end it by stating your name, your owner order "
            "and your next step, and wait for the owner's next message before any other work."
        )
        return f"{_identity(ev)} {then}{_notes(note)}"
    return f"{_COMPACTED} {_identity(ev)}{_notes()}"


def main() -> int:
    # A reminder must never break a session: an unreadable payload or a closed stdout is not an
    # error worth surfacing.
    try:
        text = _text(read_event())
    except _UNREADABLE:
        text = (
            ""
            if read_event().get("hook_event_name") == "UserPromptSubmit"
            else _COMPACTED
        )
    with contextlib.suppress(OSError):
        if text:
            sys.stdout.write(text + "\n")
    return 0


sys.exit(main())
